B.kb=new A.lS(0,"somali")
B.aot=new A.bZ("\ud83d\udc2a","Beri hore, geel yar oo la yiraahdo Geli wuxuu ku noolaa dhul qallalan.","Long ago, a young camel named Geli lived on dry land.","\u0641\u064a \u0642\u062f\u064a\u0645 \u0627\u0644\u0632\u0645\u0627\u0646\u060c \u0639\u0627\u0634 \u062c\u0645\u0644 \u0635\u063a\u064a\u0631 \u0627\u0633\u0645\u0647 \u062c\u0644\u064a \u0641\u064a \u0623\u0631\u0636 \u062c\u0627\u0641\u0629.")
B.aoD=new A.bZ("\u2600\ufe0f","Maalin maalmaha ka mid ah, qorraxdu waxay u dhalaashay sida dahab.","One day, the sun shone like gold.","\u0641\u064a \u064a\u0648\u0645 \u0645\u0646 \u0627\u0644\u0623\u064a\u0627\u0645\u060c \u0623\u0634\u0631\u0642\u062a \u0627\u0644\u0634\u0645\u0633 \u0643\u0627\u0644\u0630\u0647\u0628.")
B.aoN=new A.bZ("\ud83c\udf0a","Geli wuxuu maqlay in baddu ay tahay meel cajiib ah \u2014 wuxuu goostay inuu arko!","Geli heard the sea was wonderful \u2014 he decided to see it!","\u0633\u0645\u0639 \u062c\u0644\u064a \u0623\u0646 \u0627\u0644\u0628\u062d\u0631 \u0645\u0643\u0627\u0646 \u0631\u0627\u0626\u0639 \u2014 \u0642\u0631\u0631 \u0623\u0646 \u064a\u0631\u0627\u0647!")
B.aoI=new A.bZ("\ud83c\udfd6\ufe0f",'Markuu yimid xeebta, wuxuu arkay cir buluug ah iyo hirar cadcad. "Waa qurux!" ayuu yiri.','At the beach he saw blue sky and white waves. "So beautiful!" he said.','\u0639\u0646\u062f \u0627\u0644\u0634\u0627\u0637\u0626 \u0631\u0623\u0649 \u0633\u0645\u0627\u0621 \u0632\u0631\u0642\u0627\u0621 \u0648\u0623\u0645\u0648\u0627\u062c\u0627\u064b \u0628\u064a\u0636\u0627\u0621. \u0642\u0627\u0644: "\u0645\u0627 \u0623\u062c\u0645\u0644\u0647\u0627!"')
B.aoz=new A.bZ("\u2b50","Geli wuxuu bartay in safarku uu baro wax cusub \u2014 sidaad adna u baran karto maalin kasta!","Geli learned that travel teaches new things \u2014 just like you can every day!","\u062a\u0639\u0644\u0645 \u062c\u0644\u064a \u0623\u0646 \u0627\u0644\u0633\u0641\u0631 \u064a\u0639\u0644\u0651\u0645 \u0623\u0634\u064a\u0627\u0621 \u062c\u062f\u064a\u062f\u0629 \u2014 \u0645\u062b\u0644\u0643 \u0643\u0644 \u064a\u0648\u0645!")
B.a6Q=s([B.aot,B.aoD,B.aoN,B.aoI,B.aoz],t.Ij)
B.aoT=new A.cY("so_camel_sky",B.kb,"Geela iyo Cirka Buluugga ah","The Camel and the Blue Sky","\u0627\u0644\u062c\u0645\u0644 \u0648\u0627\u0644\u0633\u0645\u0627\u0621 \u0627\u0644\u0632\u0631\u0642\u0627\u0621",3,B.a6Q)
B.aog=new A.bZ("\ud83d\udc67","Ayaan waxay la tagtay hooyadeed suuqa si ay u iibsadaan khudaar cusub.","Ayaan went to the market with her mother to buy fresh vegetables.","\u0630\u0647\u0628\u062a \u0639\u064a\u0627\u0646 \u0645\u0639 \u0623\u0645\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0633\u0648\u0642 \u0644\u0634\u0631\u0627\u0621 \u062e\u0636\u0631\u0648\u0627\u062a \u0637\u0627\u0632\u062c\u0629.")
B.aou=new A.bZ("\ud83e\udd55",'"Salaan!" ayay tidhi ganacsatada. "Ma haysaa karooto?"','"Hello!" she said to the seller. "Do you have carrots?"','"\u0645\u0631\u062d\u0628\u0627\u064b!" \u0642\u0627\u0644\u062a \u0644\u0644\u0628\u0627\u0626\u0639. "\u0647\u0644 \u0639\u0646\u062f\u0643 \u062c\u0632\u0631\u061f"')
B.aoK=new A.bZ("\ud83c\udf4c","Waxay arkeen muus, canab, iyo basbaas cas. Mid walba wuxuu lahaa midab qurux badan.","They saw bananas, grapes, and red peppers. Each had a beautiful color.","\u0631\u0623\u0648\u0627 \u0645\u0648\u0632\u0627\u064b \u0648\u0639\u0646\u0628\u0627\u064b \u0648\u0641\u0644\u0641\u0644\u0627\u064b \u0623\u062d\u0645\u0631. \u0644\u0643\u0644 \u0644\u0648\u0646 \u062c\u0645\u064a\u0644.")
B.anZ=new A.bZ("\ud83d\udcac",'Ayaan waxay ku celcelisay erayada Soomaaliga: "Waa qaalisan tahay!" iyo "Mahadsanid!"','Ayaan practiced Somali words: "It is delicious!" and "Thank you!"','\u062a\u062f\u0631\u0628\u062a \u0639\u064a\u0627\u0646 \u0639\u0644\u0649 \u0643\u0644\u0645\u0627\u062a: "\u0625\u0646\u0647 \u0644\u0630\u064a\u0630!" \u0648"\u0634\u0643\u0631\u0627\u064b!"')
B.aaZ=s([B.aog,B.aou,B.aoK,B.anZ],t.Ij)
B.ap5=new A.cY("so_market",B.kb,"Suuqa Muqdisho","The Market Adventure","\u0645\u063a\u0627\u0645\u0631\u0629 \u0627\u0644\u0633\u0648\u0642",3,B.aaZ)
B.nM=new A.lS(1,"islamic")
B.aob=new A.bZ("\ud83d\udd4c","Axmed wuxuu maqlay in sadaqadu ay qalbigiisa ka dhigto mid ifaya.","Ahmed heard that charity makes the heart glow.","\u0633\u0645\u0639 \u0623\u062d\u0645\u062f \u0623\u0646 \u0627\u0644\u0635\u062f\u0642\u0629 \u062a\u062c\u0639\u0644 \u0627\u0644\u0642\u0644\u0628 \u064a\u0646\u0648\u0631.")
B.aod=new A.bZ("\ud83c\udf5e","Wuxuu haystay hal rooti. Wuxuu arkay wiil gaajaysan oo waddo ag taagan.","He had one piece of bread. He saw a hungry boy by the road.","\u0643\u0627\u0646 \u0644\u062f\u064a\u0647 \u0631\u063a\u064a\u0641 \u0648\u0627\u062d\u062f. \u0631\u0623\u0649 \u0648\u0644\u062f\u0627\u064b \u062c\u0627\u0626\u0639\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642.")
B.aoq=new A.bZ("\ud83d\udc9a","Axmed wuxuu siiyay nuskii rootiga. Wiilkii wuu qoslay oo mahadceliyay.","Ahmed gave half the bread. The boy smiled and thanked him.","\u0623\u0639\u0637\u0649 \u0623\u062d\u0645\u062f \u0646\u0635\u0641 \u0627\u0644\u0631\u063a\u064a\u0641. \u0627\u0628\u062a\u0633\u0645 \u0627\u0644\u0648\u0644\u062f \u0648\u0634\u0643\u0631\u0647.")
B.aoL=new A.bZ("\u2728","Nebi Muxammad \ufdfa wuxuu yiri: ficil yar oo wanaagsan ayaa qiimo weyn leh. Axmed wuu dareemay farxad.","The Prophet \ufdfa said: a small good deed has great value. Ahmed felt happy.","\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa: \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u0648\u0644\u0648 \u0635\u063a\u064a\u0631\u0627\u064b \u0639\u0638\u064a\u0645. \u0634\u0639\u0631 \u0623\u062d\u0645\u062f \u0628\u0627\u0644\u0633\u0639\u0627\u062f\u0629.")
B.abt=s([B.aob,B.aod,B.aoq,B.aoL],t.Ij)
B.aoR=new A.cY("islam_kindness",B.nM,"Sadaqada Yar","The Small Charity","\u0627\u0644\u0635\u062f\u0642\u0629 \u0627\u0644\u0635\u063a\u064a\u0631\u0629",3,B.abt)
B.aoe=new A.bZ("\ud83c\udf27\ufe0f","Roobkii wuu daayay muddo dheer. Beeraleydu wuxuu sugayay biyaha.","Rain had not fallen for a long time. The farmer waited for water.","\u0644\u0645 \u062a\u0645\u0637\u0631 \u0644\u0641\u062a\u0631\u0629 \u0637\u0648\u064a\u0644\u0629. \u0627\u0646\u062a\u0638\u0631 \u0627\u0644\u0645\u0632\u0627\u0631\u0639 \u0627\u0644\u0645\u0627\u0621.")
B.aoJ=new A.bZ("\ud83e\udd32",'Maalin kasta wuxuu Alle u duceeyay: "Rabbiyow, nagu naxariiso."','Every day he prayed to Allah: "My Lord, have mercy on us."','\u0643\u0644 \u064a\u0648\u0645 \u062f\u0639\u0627 \u0627\u0644\u0644\u0647: "\u0631\u0628\u0646\u0627 \u0627\u0631\u062d\u0645\u0646\u0627."')
